#include <string>

class EmergencyCall {
public:
    EmergencyCall(std::string incident, std::string location)
        : incident_(incident), location_(location) {}

    void updateLocation(const std::string& newLocation) {
        location_ = newLocation;
    }

    const std::string& incident() const {
        return incident_;
    }

    const std::string& location() const {
        return location_;
    }

private:
    std::string incident_;
    std::string location_;
};

class DispatchTracker {
public:
    DispatchTracker() : watched_(nullptr) {}

    void beginWatching(EmergencyCall& call) {
        watched_ = &call;
    }

    void switchTo(EmergencyCall& call) {
        watched_ = &call;
    }

    void clear() {
        watched_ = nullptr;
    }

    bool isWatching() const {
        return watched_ != nullptr;
    }

    std::string watchedLocation() const {
        return watched_ == nullptr ? "No active call" : watched_->location();
    }

private:
    EmergencyCall* watched_;
};
